import os

def clear_files(root_dir):
    for path, subdirs, files in os.walk(root_dir):
        for file in files:
            if '.tmp' in file:
                file_path = os.path.join(path, file)
                try:
                    os.chmod(file_path, 0o777)
                    os.remove(file_path)
                except OSError as e:
                    print(f"Error: {e}")

