import os

def get_dir_size(directory):
    total = 0
    for name in os.listdir(directory):
        full_path = os.path.join(directory, name)
        if os.path.isfile(full_path):
            total += os.path.getsize(full_path)
        else:
            total += get_dir_size(full_path)

    return total

