import os
def list_images(path):
    images = []
    for filename in os.listdir(path):
        if filename.endswith('.jpg'):
            images.append(filename)

    return images

def create_album(images):
    html = '<html><body>'
    for image in images:
        thumbnail = get_thumbnail(image)
        html += f"<img src='{thumbnail}'>"

    html += '</body></html>'
    with open('album.html', 'w') as f:
        f.write(html)

def get_thumbnail(image):
    os.system(f"convert {image} -thumbnail 128x128 {image}.thumb")
    return image + '.thumb'

