import os
import shutil

def move_photos(src, dest):
    if not os.path.exists(dest):
        os.mkdir(dest)
    for filename in os.listdir(src):
        filepath = os.path.join(src, filename)
        if 'photo' in filepath:
            shutil.move(filepath, dest)
    shutil.rmtree(src)

