import requests

def make_profile_request(user):
    url = 'http://example.com/api/user_profile'
    headers = {'Authorization': f'Bearer {get_user_token(user)}'}
    response = requests.get(url, headers=headers)
    return response.json()

def update_address(user, address):
    profile = make_profile_request(user)
    profile['address'] = address
    requests.put(
        'http://example.com/api/update_profile',
        json={'profile': profile}
    )

